import React, { useEffect } from "react";
import logo from "./logo.png";
import "./Navbar.css";
import { Link } from "react-router-dom";

interface Props {}

const Navbar = (props: Props) => {
  useEffect(() => {document.body.style.backgroundColor = '#222020ff'})
  
  return (
    <nav className="relative container mx-auto p-6 bg-dgray">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-20">
            <Link to = "/">
            <img src={logo} alt="" />
            </Link>
          
          <div className="hidden font-bold lg:flex">
            <Link to = "/search"  className="text-white hover:text-darkBlue">
              Search
            </Link>
          </div>
        </div>
        <div className="hidden lg:flex items-center space-x-6 text-white">
          <div className="hover:text-darkBlue">Login</div>
          <a
            href=""
            className="px-8 py-3 font-bold rounded text-black bg-mint hover:opacity-70"
          >
            Signup
          </a>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
